package backend

import "fmt"

// Item is one item returned by GET /items.
type Item struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

// ItemsRequest is the GET /items query. A nil Cursor is the initial request.
type ItemsRequest struct {
	Cursor *string
	Limit  int
}

// ItemsResponse is the structured GET /items response.
type ItemsResponse struct {
	Items      []Item  `json:"items"`
	NextCursor *string `json:"next_cursor"`
}

// FetchItems consumes cursor and limit and returns one page.
func FetchItems(request ItemsRequest) (ItemsResponse, error) {
	if request.Limit < 1 {
		return ItemsResponse{}, fmt.Errorf("limit must be at least 1")
	}

	start := 0
	if request.Cursor != nil {
		switch *request.Cursor {
		case "cursor-2":
			start = 2
		default:
			return ItemsResponse{}, fmt.Errorf("unknown cursor %q", *request.Cursor)
		}
	}

	all := []Item{
		{ID: "i1", Name: "one"},
		{ID: "i2", Name: "two"},
		{ID: "i3", Name: "three"},
	}
	end := start + request.Limit
	if end > len(all) {
		end = len(all)
	}

	response := ItemsResponse{Items: all[start:end]}
	if end < len(all) {
		next := fmt.Sprintf("cursor-%d", end)
		response.NextCursor = &next
	}
	return response, nil
}

// FetchAllItems requests the next page with the exact cursor returned by the
// preceding response, and stops without another request when it is nil.
func FetchAllItems(limit int) ([]Item, error) {
	var cursor *string
	var items []Item

	for {
		response, err := FetchItems(ItemsRequest{Cursor: cursor, Limit: limit})
		if err != nil {
			return nil, err
		}
		items = append(items, response.Items...)
		if response.NextCursor == nil {
			return items, nil
		}
		cursor = response.NextCursor
	}
}

