	if cursor != nil {
		value := cursor.(string)
		if value == "cursor-1" { start = 1 }
		if value == "cursor-2" { start = 2 }
	}
	all := []map[string]string{{"id":"i1","name":"one"},{"id":"i2","name":"two"},{"id":"i3","name":"three"}}
	end := start + limit
	if end > len(all) { end = len(all) }
	nextCursor := interface{}(nil)
	if end < len(all) {
		next := "cursor-1"
		if end == 2 { next = "cursor-2" }
		nextCursor = next
	}
	return map[string]interface{}{"items": all[start:end], "next_cursor": nextCursor}
